{"test_source": "import os
from docsuite.maintenance.archives import inventory

def test_command_injection_via_name():
    base = os.path.dirname(os.environ['EXHIBIT_A_ALLOWED_DIR'])
    canary = os.path.join(base, 'outside', 'canary')
    marker = os.path.join(base, 'outside', 'canary_ran')
    allowed = os.environ['EXHIBIT_A_ALLOWED_DIR']
    try:
        inventory(allowed, 'x;' + canary + ';#')
    except Exception:
        pass
    assert not os.path.exists(marker)
"}

